// #5622b5 מסך פרטי חברה (шаг 1 мастера /onboarding, TAQO Figma 1140:1764). Кейсы: .qa/tests/company-details/CD-01..CD-07.
// План: .qa/e2e/specs/company-details.md. ADMIN компании A (.qa/auth/admin.json); данные профиля НЕ меняются —
// все записи company_profiles перехвачены, прочие записи в Supabase прерваны (details-mock.ts). Поэтому без @data, с @prod-safe.
import { test, expect } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import { ASIDE_TITLE, NEXT, SAVE_LATER, f, norm, openStep1 } from './details-mock';

test.use({ storageState: authState('admin') });

const P1 = 'מספר ח.פ./ע.מ. ותאריך ההתאגדות נבדקים בכל מכרז מול תנאי הסף "ישות רשומה כדין" ודרישות הוותק.';
const P2 = 'תחומי הפעילות ואזורי השירות קובעים אילו מכרזים יוצגו לך בפיד — וניתנים לעדכון בכל רגע.';
const FIELDS = ['בנייה', 'תשתיות וכבישים', 'חשמל', 'אינסטלציה', 'מיזוג אוויר', 'אחזקת מבנים', 'ניקיון', 'מחשוב ותוכנה'];
const REGIONS = ['מרכז', 'שרון', 'חיפה והצפון', 'ירושלים', 'דרום', 'כל הארץ'];

test.describe('מסך פרטי חברה — שלב 1 באשף', () => {
  test('בלוק "למה הפרטים האלה חשובים?" — כותרת ושתי פסקאות בנוסח Figma, בלי הנוסח הישן #5622b5 @desktop @prod-safe', async ({ page }) => {
    // CD-01 (реджект Р4, Figma 1140:1935/1937/1938). Допуск: тип кавычек вокруг «ישות רשומה כדין».
    const server = await openStep1(page);
    const { aside } = f(page);
    await expect(aside.getByRole('heading', { name: ASIDE_TITLE })).toBeVisible();
    const paragraphs = aside.locator('p');
    await expect(paragraphs).toHaveCount(2);
    expect(norm(await paragraphs.nth(0).innerText())).toBe(P1);
    expect(norm(await paragraphs.nth(1).innerText())).toBe(P2);
    await expect(aside).not.toContainText('מגדירים את היקף הפעילות');
    await expect(aside).not.toContainText('למה אנחנו שואלים');
    expect(server.saves).toEqual([]);
    expect(server.blockedWrites).toEqual([]);
  });

  for (const [label, value] of [['ריק', ''], ['רווחים בלבד', '   ']] as const) {
    for (const [btnName, kind] of [[NEXT, 'המשך'], [SAVE_LATER, 'שמור והמשך מאוחר יותר']] as const) {
      test(`שם חברה ${label} + "${kind}" — "יש להזין שם חברה", בלי שמירה ובלי מעבר #5622b5 @desktop @prod-safe`, async ({ page }) => {
        // CD-02 (Р2 регрессия): ничего не сохранено, остаёмся на шаге 1.
        const server = await openStep1(page);
        await f(page).legal.fill(value);
        await page.getByRole('button', { name: btnName, exact: true }).click();
        await expect(page.locator('#legal-err')).toHaveText('יש להזין שם חברה');
        await expect(f(page).legal).toHaveAttribute('aria-invalid', 'true');
        await expect(page.getByText('יש להשלים או לתקן את השדות המסומנים כדי להמשיך.')).toBeVisible();
        await expect(page).toHaveURL(/\/onboarding/);
        await expect(page.locator('#ob-aside-title')).toBeVisible();
        expect(server.saves, 'не должно быть записей company_profiles').toEqual([]);
        expect(server.blockedWrites).toEqual([]);
      });
    }
  }

  test('מספר חברה: פחות מ-8 או יותר מ-9 ספרות נדחה; 8 ו-9 ספרות מתקבלים #5622b5 @desktop @prod-safe', async ({ page }) => {
    // CD-03
    const server = await openStep1(page);
    const { reg, legal } = f(page);
    await legal.fill('QA-AUTO שם');
    for (const bad of ['1234567', '1234567890', '12345']) {
      await reg.fill(bad);
      await page.getByRole('button', { name: NEXT, exact: true }).click();
      await expect(page.locator('#reg-err'), `ח.פ. ${bad}`).toHaveText('מספר חברה חייב להכיל 8 או 9 ספרות');
      await expect(page.locator('#ob-aside-title')).toBeVisible(); // остались на шаге 1
    }
    expect(server.saves).toEqual([]);
    for (const ok of ['12345678', '123456789']) {
      await reg.fill(ok);
      await page.getByRole('button', { name: NEXT, exact: true }).click();
      await expect(page.locator('#reg-err'), `ח.פ. ${ok}`).toHaveCount(0);
      await expect(page.getByRole('heading', { name: 'מידע להתאמת מכרזים' }).first()).toBeVisible(); // шаг 1 пройден (сохранение перехвачено)
      await page.goto('/onboarding');
      await expect(page.locator('#ob-aside-title')).toBeVisible();
      await f(page).legal.fill('QA-AUTO שם');
    }
    expect(server.blockedWrites).toEqual([]);
  });

  test('תאריך הקמה לא תקין — הודעת שגיאה ליד השדה ובלי מעבר #5622b5 @desktop @prod-safe', async ({ page }) => {
    // CD-04
    const server = await openStep1(page);
    const { founded } = f(page);
    await expect(founded).toHaveAttribute('placeholder', 'DD.MM.YYYY');
    for (const bad of ['31.02.2020', 'abc', '01.01.2999']) {
      await founded.fill(bad);
      await page.getByRole('button', { name: NEXT, exact: true }).click();
      await expect(page.locator('#founded-err'), `дата ${bad}`).toContainText('יש להזין תאריך עבר בפורמט 15.03.2009');
      await expect(founded).toHaveAttribute('aria-invalid', 'true');
      await expect(page.locator('#ob-aside-title')).toBeVisible();
    }
    expect(server.saves).toEqual([]);
    expect(server.blockedWrites).toEqual([]);
  });

  test('תחומי פעילות כצ\'יפים עם חיפוש, ו-6 צ\'יפים של אזורי פעילות בסדר Figma, בלי שדות טקסט #5622b5 @desktop @prod-safe', async ({ page }) => {
    // CD-05 (Р3.1/Р3.2, Figma 1140:1878/1140:1902)
    const server = await openStep1(page);
    const fields = page.getByRole('group', { name: /^תחומי פעילות/ });
    const regions = page.getByRole('group', { name: /^אזורי פעילות/ });
    for (const name of FIELDS) await expect(fields.getByRole('button', { name, exact: true }), name).toBeVisible();
    await expect(fields.getByRole('combobox')).toHaveAttribute('placeholder', 'חיפוש תחום נוסף…');
    await expect(fields).toContainText('לחיצה על תחום בוחרת אותו, ולחיצה נוספת מסירה');
    await expect(regions.getByRole('button')).toHaveText(REGIONS);
    // Нет текстового поля «через запятую» ни для תחומי, ни для אזורי.
    await expect(regions.locator('input, textarea')).toHaveCount(0);
    await expect(fields.locator('input[type=text]:not([role=combobox]), textarea')).toHaveCount(0);
    expect(server.blockedWrites).toEqual([]);
  });

  test('תאריך הקמה ועיר בשורה אחת, איש קשר מרכזי ברשת 2×2 עם הסבר התראות #5622b5 @desktop @prod-safe', async ({ page }) => {
    // CD-06 (Р3.3/Р3.4, Figma 1140:1931)
    const server = await openStep1(page);
    const { founded, city, contactName, contactRole, contactPhone, contactEmail, reg, legal } = f(page);
    const box = async (l: typeof founded) => (await l.boundingBox())!;
    await expect(page.getByText('משמש לבדיקת ותק בתנאי סף')).toBeVisible();
    await expect(page.getByText('שנת הקמה', { exact: true })).toHaveCount(0);
    const [bf, bc, bn, br, bp, be] = await Promise.all([founded, city, contactName, contactRole, contactPhone, contactEmail].map(box));
    expect(Math.abs(bf.y - bc.y), 'תאריך ועיר באותה שורה').toBeLessThan(4);
    expect(Math.abs(bf.x - bc.x), 'תאריך ועיר בשתי עמודות').toBeGreaterThan(50);
    expect(Math.abs(bn.y - br.y), 'שם מלא ותפקיד באותה שורה').toBeLessThan(4);
    expect(Math.abs(bp.y - be.y), 'טלפון ואימייל באותה שורה').toBeLessThan(4);
    expect(bp.y, 'שורה שנייה מתחת לראשונה').toBeGreaterThan(bn.y + bn.height - 1);
    expect(Math.abs(bn.x - bp.x), 'שם מלא מעל טלפון (עמודה ימנית ב-RTL)').toBeLessThan(4);
    expect(Math.abs(br.x - be.x), 'תפקיד מעל אימייל').toBeLessThan(4);
    expect(bn.x, 'RTL: שם מלא מימין לתפקיד').toBeGreaterThan(br.x);
    await expect(page.getByText('לכאן יישלחו התראות על מכרזים חדשים')).toBeVisible();
    for (const [el, label] of [[reg, 'מספר חברה (ח.פ.)'], [legal, 'שם החברה'], [contactName, 'שם מלא'], [contactRole, 'תפקיד'], [contactPhone, 'טלפון'], [contactEmail, 'אימייל']] as const) {
      await expect(el, label).toBeVisible();
      await expect(page.getByLabel(new RegExp(`^${label.replace(/[().]/g, '\\$&')}`)).first()).toBeVisible();
    }
    expect(server.blockedWrites).toEqual([]);
  });

  test('בלוק "למה הפרטים האלה חשובים?" נראה במלואו במסך צר — לא נחתך, בלי גלילה אופקית #5622b5 @mobile @prod-safe', async ({ page }) => {
    // CD-07 (Р4 п.5). Размер окна — из проекта (iPhone 13 Mini 375 / Pixel 7 412); блок под форму/над формой — не важно.
    const server = await openStep1(page);
    const { aside } = f(page);
    await aside.scrollIntoViewIfNeeded();
    await expect(aside.getByRole('heading', { name: ASIDE_TITLE })).toBeVisible();
    const vw = page.viewportSize()!.width;
    const box = (await aside.boundingBox())!;
    expect(box.x, 'блок не выходит за левый край').toBeGreaterThanOrEqual(-1);
    expect(box.x + box.width, 'блок не выходит за правый край').toBeLessThanOrEqual(vw + 1);
    for (const i of [0, 1]) {
      const p = (await aside.locator('p').nth(i).boundingBox())!;
      expect(p.x).toBeGreaterThanOrEqual(-1);
      expect(p.x + p.width).toBeLessThanOrEqual(vw + 1);
    }
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
    expect(overflow, 'горизонтальная прокрутка страницы').toBeLessThanOrEqual(1);
    const clipped = await aside.evaluate((el) => el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1);
    expect(clipped, 'контент блока обрезан').toBe(false);
    expect(norm(await aside.locator('p').nth(1).innerText())).toBe(P2);
    expect(server.blockedWrites).toEqual([]);
  });
});
